    taxExempt: false,
    keyAccount: false,
    defaultDiscountPct: [0, [Validators.required, Validators.min(0), Validators.max(100)]],
  });

  constructor() {
    afterNextRender(() => this.nameInput().nativeElement.focus());
  }

